export interface OrderAlertController {
  prepare: () => Promise<void>
  notify: () => void
  destroy: () => void
}

export function createOrderAlert(): OrderAlertController {
  let audio: any = null
  let preparing: Promise<void> | null = null
  let lastPlayedAt = 0

  async function prepare() {
    if (audio) return
    if (preparing) return preparing

    preparing = new Promise<void>((resolve) => {
      try {
        const filePath = `${wx.env.USER_DATA_PATH}/${ORDER_ALERT_FILENAME}`
        const fs = wx.getFileSystemManager()

        const createAudio = () => {
          try {
            audio = wx.createInnerAudioContext()
            audio.autoplay = false
            audio.loop = false
            audio.volume = 1
            audio.src = filePath
            audio.onError((error: unknown) => console.warn('新订单提示音播放失败', error))
          } catch (error) {
            console.warn('新订单提示音初始化失败', error)
          }
          resolve()
        }

        fs.access({
          path: filePath,
          success: createAudio,
          fail: () => {
            fs.writeFile({
              filePath,
              data: ORDER_ALERT_WAV_BASE64,
              encoding: 'base64',
              success: createAudio,
              fail: (error: unknown) => {
                console.warn('新订单提示音写入失败', error)
                resolve()
              }
            })
          }
        })
      } catch (error) {
        console.warn('新订单提示音准备失败', error)
        resolve()
      }
    })

    await preparing
  }

  function vibrate() {
    try {
      wx.vibrateShort({
        type: 'heavy',
        fail: () => {
          try { wx.vibrateShort({}) } catch {}
        }
      })
    } catch {}
  }

  function notify() {
    const current = Date.now()
    if (current - lastPlayedAt < 1500) return
    lastPlayedAt = current

    vibrate()
    void prepare().then(() => {
      if (!audio) return
      try {
        audio.stop()
        audio.seek(0)
        audio.play()
      } catch (error) {
        console.warn('新订单提示音触发失败', error)
      }
    })
  }

  function destroy() {
    try {
      audio?.destroy()
    } catch {}
    audio = null
    preparing = null
  }

  return { prepare, notify, destroy }
}
